// A refusal names the place as a path, with what is wrong said after it: `…devices[0].count must be`, `…labels.a must be`.
func TestTheRefusalOfADeployBlockNamesThePlace(t *testing.T) {
	for _, tc := range []struct{ name, deploy, want string }{
		{"a key of a block", "restart_policy: {max_attempts: x}", "services.a.deploy.restart_policy.max_attempts must be a whole number"},
		{"a device's count", "resources: {reservations: {devices: [{capabilities: [gpu], count: x}]}}", "services.a.deploy.resources.reservations.devices[0].count must be a whole number or `all`"},
		{"a device without capabilities", "resources: {reservations: {devices: [{driver: x}]}}", "services.a.deploy.resources.reservations.devices[0].capabilities is required"},
		{"a label's value", "labels: {a: [1]}", "services.a.deploy.labels.a must be a string"},
		{"an unknown key", "update_config: {a: 1}", `services.a.deploy.update_config has "a", which docker compose does not take there`},
	} {
		t.Run(tc.name, func(t *testing.T) {
			path := filepath.Join(t.TempDir(), "compose.yaml")
			if err := os.WriteFile(path, []byte("services:\n  a:\n    image: x\n    deploy:\n      "+tc.deploy+"\n"), 0o644); err != nil {
				t.Fatal(err)
			}
			_, err := Load(path)
			if err == nil {
				t.Fatal("the block was read")
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Errorf("the refusal is %q, want it to say %q", err, tc.want)
			}
		})
	}
}

// A load that goes on past a fault (the commands that take a project down) keeps what stays refused in the merged service
// of an extends as a fault of the project, and does not stop.
func TestTheRefusalOfAnExtendedDeployBlockIsKeptWhereTheLoadGoesOn(t *testing.T) {
	dir := t.TempDir()
	if err := os.WriteFile(filepath.Join(dir, "base.yaml"), []byte("services:\n  base:\n    image: x\n    deploy:\n      restart_policy: {condition: 1}\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	main := filepath.Join(dir, "compose.yaml")
	if err := os.WriteFile(main, []byte("services:\n  a:\n    extends: {file: base.yaml, service: base}\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	p, err := LoadFilesEnvDirSoft([]string{main}, nil, dir)
	if err != nil {
		t.Fatalf("the load stopped: %v", err)
	}
	if err := p.CheckValueFaults(); err == nil || !strings.Contains(err.Error(), "services.base.deploy.restart_policy.condition") {
		t.Fatalf("the fault kept is %v, want the refusal of the condition", err)
	}
}
